solution.solution.cpp:
#include <string_view>

std::string_view describe(int n)
{
    if (n > 0)
    {
        return "positive";
    }
    else if (n < 0)
    {
        return "negative";
    }
    else
    {
        return "zero";
    }
}

unitTests:
TEST("positive numbers") { CHECK_EQ(describe(5), "positive"); CHECK_EQ(describe(1), "positive"); }
TEST("negative numbers") { CHECK_EQ(describe(-5), "negative"); CHECK_EQ(describe(-1), "negative"); }
TEST("zero") { CHECK_EQ(describe(0), "zero"); }

